class Solution {
  private double best;

  public double maximumAverageSubtree(TreeNode root) {
    walk(root);
    return best;
  }

  // {sum, count} of the subtree
  private long[] walk(TreeNode node) {
    if (node == null) return new long[2];
    long[] l = walk(node.left), r = walk(node.right);
    long sum = l[0] + r[0] + node.val, count = l[1] + r[1] + 1;
    best = Math.max(best, (double) sum / count);
    return new long[] {sum, count};
  }
}
